import React, { useState, useRef } from "react";
import { useNavigate } from "react-router-dom";

const OrarSali = ({ onRoomClick }) => {
  const navigate = useNavigate();
  const [activeDropdown, setActiveDropdown] = useState(null);
  const dropdownRefs = useRef([]);

  // Listă cu săli (fără etaje)
  const sali = [
    "C2", "C112", "C210", "C308", "C309", "C401", "C403", "C405", "C409", "C411", "C412", "C413", "C901", "C903"
  ];

  // Functia de activare/desactivare a meniului dropdown
  const toggleDropdown = (index, e) => {
    e.stopPropagation();
    setActiveDropdown((prev) => (prev === index ? null : index));
  };

  // Selectează sala și navighează către URL-ul corespunzător
  const handleSalaSelect = (sala) => {
    navigate(`/app/orar/sali/${sala}`); // Navighează doar cu sala (fără etaj)
    onRoomClick(sala); // Apelează funcția prop pentru a seta sala selectată
  };

  return (
    <div className="orar-sali-container">
      <div className="orar-buttons">
        <div className="dropdown-container">
          <button
            className="orar-button"
            onClick={(e) => toggleDropdown(0, e)} // Un singur dropdown pentru toate sălile
          >
            🏫 Săli
          </button>

          {activeDropdown === 0 && (
            <div className="dropdown-menu">
              {sali.map((sala, i) => (
                <button
                  className="dropdown-item"
                  key={i}
                  onClick={() => handleSalaSelect(sala)}
                >
                  {sala}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default OrarSali;
